{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "This bill would require a public school principal to remove a student from any classroom or school-sponsored event or activity if an order of protection has been issued to protect another student in the same school.",
      "rationale": "Conveys the principal's removal duty and same-school condition, but does not specify that removal is limited to settings shared with the protected student or explicitly identify the removed student as the order's respondent."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The school or school district would be required to provide the removed student with alternative instruction for any classes they miss.",
      "rationale": "Conveys the responsible entities and the duty to provide alternative instruction for classes missed because of removal."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "This requirement would apply only for the duration of the order of protection.",
      "rationale": "In context, conveys that the required separation lasts only while the protection order is in effect."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law and would apply to orders of protection entered on or after that date.",
      "rationale": "Conveys both the effective date and the limitation to orders entered on or after that date."
    }
  ]
}
